python3 - <<'PY'
from pathlib import Path
from collections import Counter
p = Path('/Users/ramil/Documents/Клиенты все')
media_ext = {'.jpg','.jpeg','.png','.heic','.tif','.tiff','.gif','.mp4','.mov','.avi','.webp'}
doc_ext = {'.pdf','.docx','.doc','.xlsx','.xls','.pptx'}
rows = []
for child in sorted(p.iterdir(), key=lambda x: x.name.lower()):
    if child.name.startswith('.'):
        continue
    if child.is_file():
        continue
    files = [f for f in child.rglob('*') if f.is_file() and not f.name.startswith('.')]
    media = [f for f in files if f.suffix.lower() in media_ext]
    docs = [f for f in files if f.suffix.lower() in doc_ext]
    rows.append((len(media), len(docs), len(files), child.name))
rows.sort(reverse=True)
print(f'folders: {len(rows)}')
print('TOP media folders:')
for r in rows[:40]:
    print(f'  media={r[0]:3} docs={r[1]:3} files={r[2]:4}  {r[3]}')
print('\nfolders with 5+ media:')
for r in rows:
    if r[0] >= 5:
        print(f'  {r[0]:3}  {r[3]}')
PY

