function project(lat: number, lon: number, w: number, h: number) {
  const lon0 = 18;
  const lon1 = 192;
  const lat0 = 41;
  const lat1 = 78;
  return {
    x: ((lon - lon0) / (lon1 - lon0)) * w,
    y: ((lat1 - lat) / (lat1 - lat0)) * h,
  };
}

function pathFrom(ring: [number, number][], w: number, h: number) {
  return ring
    .map(([lon, lat], i) => {
      const { x, y } = project(lat, lon, w, h);
      return `${i === 0 ? "M" : "L"}${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .join(" ") + " Z";
}

function buyersByCity() {
  const map = new Map<string, Buyer[]>();
  for (const b of BUYERS) {
    const list = map.get(b.city) ?? [];
    list.push(b);
    map.set(b.city, list);
  }
  return map;
}

function RussiaMap({
  layer,
  selected,
  onSelect,
}: {
  layer: Layer;
  selected: string | null;
  onSelect: (city: string | null) => void;
}) {
  const theme = useHostTheme();
  const w = 920;
  const h = 420;
  const byCity = buyersByCity();
  const showBuyers = layer !== "crm";
  const showCrm = layer === "crm";
  const pickOnly = layer === "pick";

  return (
    <div>
      <svg
        viewBox={`0 0 ${w} ${h}`}
        width="100%"
        style={{ display: "block", background: theme.bg.editor }}
      >
        <path d={pathFrom(RUSSIA, w, h)} fill={theme.fill.tertiary} stroke={theme.stroke.secondary} strokeWidth={1} />
        <path d={pathFrom(KALININGRAD, w, h)} fill={theme.fill.tertiary} stroke={theme.stroke.secondary} strokeWidth={1} />
        {showCrm &&
          CRM_CITIES.filter((c) => CITY_XY[c.city] && c.n > 0).map((c) => {
            const { x, y } = project(CITY_XY[c.city].lat, CITY_XY[c.city].lon, w, h);
            const r = 4 + Math.sqrt(c.n) * 2.2;
            return (
              <g key={`crm-${c.city}`} onClick={() => onSelect(c.city)} style={{ cursor: "pointer" }}>
                <circle cx={x} cy={y} r={r} fill={theme.fill.secondary} stroke={theme.stroke.primary} strokeWidth={1} opacity={0.85} />
              </g>
            );
          })}
        {showBuyers &&
          Array.from(byCity.entries()).map(([city, list]) => {
            const xy = CITY_XY[city];
            if (!xy) return null;
            const notable = list.some((b) => b.review || b.site);
            if (pickOnly && !notable) return null;
            const { x, y } = project(xy.lat, xy.lon, w, h);
            const r = 5 + Math.sqrt(list.length) * 3.4;
            const active = selected === city;
            const fill = notable ? theme.accent.primary : theme.fill.primary;
            return (
              <g key={city} onClick={() => onSelect(active ? null : city)} style={{ cursor: "pointer" }}>
                <circle
                  cx={x}
                  cy={y}
                  r={r}
                  fill={fill}
                  opacity={active ? 1 : 0.88}
                  stroke={active ? theme.text.primary : "transparent"}
                  strokeWidth={2}
                />
                {list.length > 1 && (
                  <text
                    x={x}
                    y={y + 3.5}
                    textAnchor="middle"
                    fontSize={10}
                    fill={theme.text.onAccent}
                    style={{ pointerEvents: "none" }}
                  >
                    {list.length}
                  </text>
                )}
              </g>
            );
          })}
        {["Москва", "Самара", "Новороссийск", "Владивосток", "Якутск", "Мурманск", "Астрахань"].map((city) => {
          const xy = CITY_XY[city];
          if (!xy) return null;
          const { x, y } = project(xy.lat, xy.lon, w, h);
          return (
            <text key={`lbl-${city}`} x={x + 10} y={y - 8} fontSize={11} fill={theme.text.tertiary}>
              {city}
            </text>
          );
        })}
      </svg>
      <Text size="small" tone="tertiary">
