      </Text>
    </div>
  );
}

function CityPanel({ city }: { city: string }) {
  const list = BUYERS.filter((b) => b.city === city);
  const crm = CRM_CITIES.find((c) => c.city === city);
  if (list.length === 0 && !crm) return null;
  return (
    <Stack gap={8}>
      <H3>
        {city}
        {list.length ? ` · ${list.length} в ОСВ` : ""}
        {crm ? ` · ${crm.n} карточек CRM` : ""}
      </H3>
      {list.length > 0 && (
        <Table
          headers={["Компания", "Объект", "Материалы", "Метка"]}
          rows={list.map((b) => [
            b.name,
            b.object,
            b.products || "—",
            b.caution ? b.caution : b.review && b.site ? "отзыв + сайт" : b.review ? "отзыв" : b.site ? "сайт" : "",
          ])}
          rowTone={list.map((b) => (b.caution ? "warning" : b.review || b.site ? "info" : undefined))}
          striped
          stickyHeader
        />
      )}
    </Stack>
  );
}

