function normLon(lon) { return lon < 0 ? lon + 360 : lon; }
function xy(lat, lon) {
  lon = normLon(lon);
  return [((lon - LON0) / (LON1 - LON0)) * W, ((LAT1 - lat) / (LAT1 - LAT0)) * H];
