const MIN_K = 1, MAX_K = 14;
const view = { k: 1, x: W / 2, y: H / 2 };
const slider = document.getElementById("zoomSlider");
const zoomPct = document.getElementById("zoomPct");
let anim = 0;

function kToSlider(k) { return Math.round(Math.log(k) / Math.log(MAX_K) * 100); }
function sliderToK(v) { return Math.pow(MAX_K, v / 100); }

function sizePins() {
  const scale = 1 / Math.sqrt(view.k);
  pins.querySelectorAll("circle").forEach(c => {
    c.setAttribute("r", (+c.dataset.r || 5) * scale);
  });
}

function applyView() {
  view.k = Math.min(MAX_K, Math.max(MIN_K, view.k));
  view.x = Math.min(W + 40, Math.max(-40, view.x));
  view.y = Math.min(H + 40, Math.max(-40, view.y));
  root.setAttribute("transform", `translate(${W/2},${H/2}) scale(${view.k}) translate(${-view.x},${-view.y})`);
  sizePins();
  slider.value = String(kToSlider(view.k));
  zoomPct.textContent = Math.round(view.k * 100) + "%";
}

function zoomAt(factor, cx, cy) {
  const px = cx ?? W / 2, py = cy ?? H / 2;
  const wx = (px - W / 2) / view.k + view.x;
  const wy = (py - H / 2) / view.k + view.y;
  view.k = Math.min(MAX_K, Math.max(MIN_K, view.k * factor));
  view.x = wx - (px - W / 2) / view.k;
  view.y = wy - (py - H / 2) / view.k;
  applyView();
}

function flyTo(k, x, y, ms) {
  const start = { k: view.k, x: view.x, y: view.y };
  const dest = { k: Math.min(MAX_K, Math.max(MIN_K, k)), x, y };
  const dur = ms ?? 280;
  const t0 = performance.now();
  cancelAnimationFrame(anim);
  const step = now => {
    const t = Math.min(1, (now - t0) / dur);
    const e = 1 - Math.pow(1 - t, 3);
    view.k = start.k + (dest.k - start.k) * e;
    view.x = start.x + (dest.x - start.x) * e;
    view.y = start.y + (dest.y - start.y) * e;
    applyView();
    if (t < 1) anim = requestAnimationFrame(step);
  };
  anim = requestAnimationFrame(step);
}

function fit() { flyTo(1, W / 2, H / 2); }

const REGIONS = {
  south: () => ({ k: 5.6, p: xy(44.95, 38.5) }),
  volga: () => ({ k: 4.4, p: xy(53.3, 50.1) }),
  ural: () => ({ k: 3.8, p: xy(56.9, 60.6) }),
  east: () => ({ k: 2.9, p: xy(48, 135) }),
};

function flyToCity(city) {
  const pts = visible().filter(it => it.city === city);
  if (!pts.length) return;
  const xs = pts.map(it => xy(it.lat, it.lon));
  const x = xs.reduce((s, p) => s + p[0], 0) / xs.length;
  const y = xs.reduce((s, p) => s + p[1], 0) / xs.length;
  flyTo(Math.max(view.k, 6.2), x, y);
}

function svgPoint(e) {
  const rect = svg.getBoundingClientRect();
  return [(e.clientX - rect.left) / rect.width * W, (e.clientY - rect.top) / rect.height * H];
}

applyView();

let drag = null;
svg.addEventListener("pointerdown", e => {
  if (e.target.classList && e.target.classList.contains("dot")) return;
  cancelAnimationFrame(anim);
  drag = { x: e.clientX, y: e.clientY, vx: view.x, vy: view.y, moved: false };
  svg.setPointerCapture(e.pointerId);
});
svg.addEventListener("pointermove", e => {
  if (!drag) return;
  const rect = svg.getBoundingClientRect();
  const sx = W / rect.width, sy = H / rect.height;
  if (Math.abs(e.clientX - drag.x) + Math.abs(e.clientY - drag.y) > 3) drag.moved = true;
  view.x = drag.vx - (e.clientX - drag.x) * sx / view.k;
  view.y = drag.vy - (e.clientY - drag.y) * sy / view.k;
  applyView();
});
svg.addEventListener("pointerup", () => { drag = null; });
svg.addEventListener("wheel", e => {
  e.preventDefault();
  cancelAnimationFrame(anim);
  let dy = e.deltaY;
  if (e.deltaMode === 1) dy *= 16;
  if (e.deltaMode === 2) dy *= 120;
  const [cx, cy] = svgPoint(e);
  zoomAt(Math.exp(-dy * (e.ctrlKey ? 0.01 : 0.0024)), cx, cy);
}, { passive: false });
svg.addEventListener("dblclick", e => {
  if (e.target.classList && e.target.classList.contains("dot")) return;
  e.preventDefault();
  const [cx, cy] = svgPoint(e);
  zoomAt(e.shiftKey ? 0.55 : 1.85, cx, cy);
});

let pinch = null;
svg.addEventListener("gesturestart", e => {
  e.preventDefault();
  pinch = { k: view.k };
}, { passive: false });
svg.addEventListener("gesturechange", e => {
  e.preventDefault();
  if (!pinch) return;
  const [cx, cy] = svgPoint(e);
  const next = Math.min(MAX_K, Math.max(MIN_K, pinch.k * e.scale));
  zoomAt(next / view.k, cx, cy);
}, { passive: false });
svg.addEventListener("gestureend", e => { e.preventDefault(); pinch = null; });

