document.addEventListener("keydown", e => {
  if (e.target.matches("input, textarea")) return;
  if (e.key === "+" || e.key === "=") zoomAt(1.22);
  else if (e.key === "-" || e.key === "_") zoomAt(0.82);
  else if (e.key === "0") fit();
  else if (e.key === "ArrowLeft") { view.x -= 40 / view.k; applyView(); }
  else if (e.key === "ArrowRight") { view.x += 40 / view.k; applyView(); }
  else if (e.key === "ArrowUp") { view.y -= 40 / view.k; applyView(); }
  else if (e.key === "ArrowDown") { view.y += 40 / view.k; applyView(); }
});

